    // 1. Null pointer check
    if ((wheel == NULL) || (next_wheel == NULL) || (next_momentum == NULL) || (saturated == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Finite checks for all inputs
    if (!adcs_is_finite_vec3(&wheel->axis_body) ||
        !isfinite(wheel->inertia_kg_m2) ||
        !isfinite(wheel->speed_rad_s) ||
        !isfinite(motor_torque) ||
        !isfinite(dt) ||
        !isfinite(speed_limit)) {
        return ADCS_E_NOT_FINITE;
    }

    // 3. Range and logic checks
    if (wheel->inertia_kg_m2 <= 0.0) {
        return ADCS_E_RANGE;
    }
    if (dt < 0.0) {
        return ADCS_E_RANGE;
    }
    if (speed_limit <= 0.0) {
        return ADCS_E_RANGE;
    }

    double axis_norm = adcs_vec3_norm(&wheel->axis_body);
    if (axis_norm <= ADCS_EPS_NORM) {
        return ADCS_E_RANGE;
    }

    // 4. Normalize axis
    double inv_norm = 1.0 / axis_norm;
    adcs_vec3_t a;
    a.x = wheel->axis_body.x * inv_norm;
    a.y = wheel->axis_body.y * inv_norm;
    a.z = wheel->axis_body.z * inv_norm;

    // 5. Compute unclamped speed: omega + torque * dt / J
    double J = wheel->inertia_kg_m2;
    double omega_current = wheel->speed_rad_s;
    double omega_unclamped = omega_current + (motor_torque * dt) / J;

    // 6. Check saturation: strictly exceeds speed_limit
    if (fabs(omega_unclamped) > speed_limit) {
        *saturated = 1;
    } else {
        *saturated = 0;
    }

    // 7. Clamp speed magnitude
    double omega_next;
    if (omega_unclamped > speed_limit) {
        omega_next = speed_limit;
    } else if (omega_unclamped < -speed_limit) {
        omega_next = -speed_limit;
    } else {
        omega_next = omega_unclamped;
    }

    // 8. Update next_wheel record
    next_wheel->axis_body = a;
    next_wheel->inertia_kg_m2 = J;
    next_wheel->speed_rad_s = omega_next;

    // 9. Calculate angular momentum h_next = J * omega_next * a
    double h_scalar = J * omega_next;
    next_momentum->x = h_scalar * a.x;
    next_momentum->y = h_scalar * a.y;
    next_momentum->z = h_scalar * a.z;

    return ADCS_OK;
}

